

CREATE TABLE `ourlink_db1`.`events` ( `EventId` INT NOT NULL , `TitleEn` VARCHAR(300) NULL DEFAULT NULL , `TitleEs` VARCHAR(300) NULL DEFAULT NULL , `TitleDe` VARCHAR(300) NULL DEFAULT NULL , `TitlePt` VARCHAR(300) NULL DEFAULT NULL , `TitleIt` VARCHAR(300) NULL DEFAULT NULL , `TitleFr` VARCHAR(300) NULL DEFAULT NULL , `Zoom` SMALLINT NOT NULL DEFAULT '3' , `Country` VARCHAR(6) NULL DEFAULT NULL , `OriginalLanguage` VARCHAR(3) NULL DEFAULT NULL , `DescriptionEn` VARCHAR(300) NULL DEFAULT NULL , `DescriptionEs` VARCHAR(300) NULL DEFAULT NULL , `DescriptionDe` VARCHAR(300) NULL DEFAULT NULL , `DescriptionPt` VARCHAR(300) NULL DEFAULT NULL , `DescriptionIt` VARCHAR(300) NULL DEFAULT NULL , `DescriptionFr` VARCHAR(300) NULL DEFAULT NULL , `StartDate` DATETIME NOT NULL , `StartDatePrecision` VARCHAR(20) NOT NULL DEFAULT 'day' , `Duration` INT NULL DEFAULT NULL , `DurationUnit` VARCHAR(20) NOT NULL DEFAULT 'day' , `BestTextQuality` VARCHAR(5) NULL DEFAULT NULL , `Place` VARCHAR(300) NULL DEFAULT NULL , `Tags` VARCHAR(500) NULL DEFAULT NULL , `AdminTags` VARCHAR(500) NULL DEFAULT NULL , `AudienceText` VARCHAR(500) NULL DEFAULT NULL , `AbbreviationEn` VARCHAR(50) NULL DEFAULT NULL , `AbbreviationEs` VARCHAR(50) NULL DEFAULT NULL , `AbbreviationDe` VARCHAR(50) NULL DEFAULT NULL , `AbbreviationPt` VARCHAR(50) NULL DEFAULT NULL , `AbbreviationFr` VARCHAR(50) NULL DEFAULT NULL , `AclResourcesId` VARCHAR(50) NOT NULL DEFAULT 'evt_public' , `Url1` VARCHAR(1000) NULL DEFAULT NULL , `Url1Label` VARCHAR(50) NULL DEFAULT NULL , `Url2` VARCHAR(1000) NULL DEFAULT NULL , `Url2Label` VARCHAR(50) NULL DEFAULT NULL , `Url3` VARCHAR(1000) NULL DEFAULT NULL , `Url3Label` VARCHAR(50) NULL DEFAULT NULL , `PublicNotes` TEXT NULL DEFAULT NULL , `PublicNotesUpdatedOn` DATETIME NULL DEFAULT NULL , `PublicNotesUpdatedBy` INT NULL DEFAULT NULL , `AdminNotes` TEXT NULL DEFAULT NULL , `AdminNotesUpdatedOn` DATETIME NULL DEFAULT NULL , `AdminNotesUpdatedBy` INT NULL DEFAULT NULL , `UpdatedOn` DATETIME NULL DEFAULT NULL , `UpdatedBy` INT NULL DEFAULT NULL , `CreatedOn` DATETIME NULL DEFAULT NULL , `CreatedBy` INT NULL DEFAULT NULL , `LegacySource` VARCHAR(255) NULL DEFAULT NULL , `LegacyFile` VARCHAR(255) NULL DEFAULT NULL , `LegacyFileDateModified` VARCHAR(255) NULL DEFAULT NULL , PRIMARY KEY (`EventId`)) ENGINE = InnoDB;
ALTER TABLE `events` CHANGE `EventId` `EventId` INT(11) NOT NULL AUTO_INCREMENT;
ALTER TABLE `events` ADD `SlugEn` VARCHAR(50) NULL DEFAULT NULL AFTER `OriginalLanguage`, ADD `SlugEs` VARCHAR(50) NULL DEFAULT NULL AFTER `SlugEn`, ADD `SlugDe` VARCHAR(50) NULL DEFAULT NULL AFTER `SlugEs`, ADD `SlugPt` VARCHAR(50) NULL DEFAULT NULL AFTER `SlugDe`, ADD `SlugIt` VARCHAR(50) NULL DEFAULT NULL AFTER `SlugPt`, ADD `SlugFr` VARCHAR(50) NULL DEFAULT NULL AFTER `SlugIt`, ADD `WikidataSubjectId` INT NULL DEFAULT NULL AFTER `SlugFr`, ADD `WikidataPropertyId` INT NULL DEFAULT NULL AFTER `WikidataSubjectId`, ADD `WikidataLinkByDefault` TINYINT(1) NOT NULL DEFAULT '0' AFTER `WikidataPropertyId`;
